// Rendering adapted from the extension's dashboard.js. Instead of the hard-coded
// mock object, the data comes from data.js, generated by pipeline/build-dashboard.mjs.
const slimeSrc = "sprites/cute.png";
const DASHBOARD_NOTE_KEY = "miro_claude_dashboard_note_dismissed";
const DATA = window.MIRO_DASHBOARD_DATA;
// The overview shows one source variant at a time (see sources.js); all sources by default.
let D = DATA;

document.addEventListener('DOMContentLoaded',()=>{
  if(!D){
    renderEmptyState();
    return;
  }
  renderMeta();
  bindDashboardNote();
  renderBubbles();
  renderSliders();
  renderProfile();
  bindNav();
});

window.addEventListener('miro:source',(event)=>{
  if(!DATA) return;
  D=DATA.variants?.[event.detail.source]||DATA;
  closeBubble();
  renderMeta();
  renderBubbles();
  renderSliders();
  renderProfile();
});

function renderEmptyState(){
  document.getElementById('dashboardNoteCopy').textContent='No data yet. Run the pipeline (see claude-dashboard/README.md) to generate data.js next to this page.';
  document.getElementById('dashboardNoteDismiss').style.display='none';
  document.querySelectorAll('.section').forEach(s=>{s.style.display='none';});
}

function renderMeta(){
  const chats=`${D.meta.chatCount} chat${D.meta.chatCount===1?'':'s'}`;
  document.getElementById('tbMeta').textContent=[chats,D.meta.rangeLabel].filter(Boolean).join(' · ');
  document.getElementById('splitsCount').textContent=`Averaged across ${chats}.`;
}

function bindDashboardNote(){
  const note=document.getElementById('dashboardNote');
  const dismiss=document.getElementById('dashboardNoteDismiss');
  if(!note||!dismiss) return;

  try{
    if(window.localStorage?.getItem(DASHBOARD_NOTE_KEY)==='true'){
      note.style.display='none';
      return;
    }
  }catch(_error){
    // Storage can be unavailable on file:// pages; just show the note.
  }

  dismiss.addEventListener('click',()=>{
    note.style.display='none';
    try{
      window.localStorage?.setItem(DASHBOARD_NOTE_KEY,'true');
    }catch(_error){
      // Ignore storage failures and still dismiss for this view.
    }
  });
}

function renderBubbles(){
  const stage=document.getElementById('bubbleStage');
  stage.innerHTML = '';
  D.areas.forEach(a=>{
    const el=document.createElement('div');
    el.className=`bubble ${a.size}`;
    el.style.cssText=`left:${a.x}%;top:${a.y}%;transform:translate(-50%,-50%);--bubble-fill:${a.color};--bubble-edge:rgba(52,44,37,0.10)`;
    el.innerHTML=`<div class="bubble-label">${esc(a.label)}</div><div class="bubble-pct">${a.pct}% of use</div>`;
    el.addEventListener('click',(e)=>openBubble(a,el,e));
    stage.appendChild(el);
  });
}

function openBubble(area,el,e){
  e.stopPropagation();
  const all=document.querySelectorAll('.bubble');
  const was=el.classList.contains('active');
  all.forEach(b=>b.classList.remove('active','dimmed'));

  if(was){
    closeBubble();
    return;
  }

  el.classList.add('active');
  all.forEach(b=>{if(b!==el)b.classList.add('dimmed')});

  document.getElementById('bpPlaceholder').style.display='none';
  const c=document.getElementById('bpContent');
  c.className='bp-content open';
  c.innerHTML=`
    <div class="bp-top">
      <div class="bp-title">${esc(area.label)}</div>
      <button class="bp-close" type="button" aria-label="Close area detail">×</button>
    </div>
    <div class="bp-pct">${area.pct}% of your AI activity · ${area.sessions} chat${area.sessions===1?'':'s'}</div>
    <div class="bp-section">
      <div class="bp-label">What this usually involves</div>
      <div class="bp-text">${esc(area.includes)}</div>
    </div>
    <div class="bp-section">
      <div class="bp-label">Patterns</div>
      <div class="bp-text">${esc(area.patterns)}</div>
    </div>
    <div class="bp-section">
      <div class="bp-label">Where this helps</div>
      <div class="bp-text">${esc(area.helps)}</div>
    </div>
    <div class="bp-section">
      <div class="bp-label">Where this can get in the way</div>
      <div class="bp-text">${esc(area.risk)}</div>
    </div>
    <div class="bp-section">
      <div class="bp-label">Try this next time</div>
      <div class="bp-text"><strong>${esc(area.try)}</strong></div>
    </div>
  `;
  c.querySelector('.bp-close')?.addEventListener('click', closeBubble);
}

function closeBubble(){
  document.querySelectorAll('.bubble').forEach(b=>b.classList.remove('active','dimmed'));
  document.getElementById('bpPlaceholder').style.display='flex';
  document.getElementById('bpContent').className='bp-content';
  document.getElementById('bpContent').innerHTML='';
}

function renderSliders(){
  const card=document.getElementById('slidersCard');
  card.innerHTML=D.aspects.map(a=>`
    <button class="slider-row" type="button">
      <div class="slider-row-top">
        <div class="slider-label">${esc(a.label)}</div>
        <div class="slider-row-right">
          <div class="slider-verdict ${esc(a.tone)}">${esc(a.verdict)}</div>
          <div class="slider-chevron">+</div>
        </div>
      </div>
      <div class="slider-scale-labels"><span class="ai-label">AI</span><span class="you-label">You</span></div>
      <div class="slider-track">
        <div class="slider-track-left"></div>
        <div class="slider-track-right"></div>
        <div class="slider-range-fill" style="left:${a.lo}%;width:${a.hi-a.lo}%"></div>
        <div class="slider-tick" style="left:${a.lo}%"></div>
        <div class="slider-tick" style="left:${a.hi}%"></div>
        <div class="slider-dot" style="left:${a.position}%"></div>
      </div>
      <div class="slider-expanded">
        <div class="slider-exp-line trend">${esc(a.trendLine)}</div>
        <div class="slider-exp-line">${esc(a.detail)}</div>
      </div>
    </button>
  `).join('');
  document.querySelectorAll('.slider-row').forEach(row=>{
    row.addEventListener('click',()=>{
      const was=row.classList.contains('open');
      document.querySelectorAll('.slider-row').forEach(r=>r.classList.remove('open'));
      if(!was)row.classList.add('open');
    });
  });
}

function renderProfile(){
  const g=document.getElementById('profileGrid');
  const p=D.profile;
  const mini=(labelClass,label,card)=>`
        <div class="profile-mini">
          <div class="pc-label ${labelClass}">${label}</div>
          <div class="pc-title">${esc(card.title)}</div>
          <div class="pc-body">${rich(card.body)}</div>
          <div class="pc-tags">${card.tags.map(t=>`<span class="pc-tag">${esc(t)}</span>`).join('')}</div>
        </div>`;
  g.innerHTML=`
    <div class="profile-hero">
      <div class="profile-hero-top">
        <img class="profile-sprite" src="${slimeSrc}" alt="Miro slime"/>
        <div class="profile-hero-text">
          <div class="profile-kicker">How we tend to work together</div>
          <div class="profile-hero-title">${esc(p.heroTitle)}</div>
          <div class="profile-hero-body">${rich(p.summary)}</div>
          <div class="profile-pill">${esc(p.dynamicPill)}</div>
        </div>
      </div>
      <div class="profile-triptych">
        ${mini('you-l','You tend to be',p.you)}
        ${mini('ai-l','AI tends to become',p.ai)}
        ${mini('rel-l','Together, the pattern is',p.together)}
      </div>
      <div class="slime-stack">
        <div class="slime-note helps">
          <div class="slime-copy"><span class="note-title">What&apos;s working</span>${esc(p.helps)}</div>
        </div>
        <div class="slime-note risk">
          <div class="slime-copy"><span class="note-title">How to prompt better</span>${esc(p.risk)}</div>
        </div>
        <div class="slime-note next">
          <div class="slime-copy"><span class="note-title">Watch for this</span>${esc(p.next)}</div>
        </div>
      </div>
    </div>
  `;
}

function bindNav(){
  const links=document.querySelectorAll('.tb-nav a');
  const sections=document.querySelectorAll('.section');
  const observer=new IntersectionObserver(entries=>{
    entries.forEach(e=>{
      if(e.isIntersecting){
        links.forEach(l=>l.classList.toggle('active',l.getAttribute('href')==='#'+e.target.id));
      }
    });
  },{rootMargin:'-30% 0px -50% 0px'});
  sections.forEach(s=>observer.observe(s));
}

function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}

// Generated copy may bold a phrase with **...**; everything else is escaped.
function rich(v){return esc(v).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');}
